# Analyze the 2-point triangle
pts = [(2,7), (3,5), (5,6)]

import math

def dist(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2)

d12 = dist(pts[0], pts[1])  # (2,7)->(3,5)
d23 = dist(pts[1], pts[2])  # (3,5)->(5,6)
d13 = dist(pts[0], pts[2])  # (2,7)->(5,6)

print(f"Dists: ({d12:.2f}, {d23:.2f}, {d13:.2f})")
print("Isosceles?", abs(d12-d23)<0.01 or abs(d12-d13)<0.01 or abs(d23-d13)<0.01)

# Check orientation of the 2-point triangle
def tri_area(p1, p2, p3):
    return abs((p1[0]*(p2[1]-p3[1]) + p2[0]*(p3[1]-p1[1]) + p3[0]*(p1[1]-p2[1]))/2)

area = tri_area(*pts)
print(f"Triangle area: {area}")

# Exact diagonal line cells
print("\nExact diagonal line cells:")
for r in range(10):
    for diag_start in [15, 16, 17]:
        c = diag_start - r
        if 0 <= c < 19:
            print(f"  ({r},{c}): part of diagonal from top-edge (0,{diag_start})")

# Region between all three diagonals
print("\nRegion between all three diagonals:")
for r in range(10):
    cells = []
    for diag_start in [15, 16, 17]:
        c = diag_start - r
        if 0 <= c < 19:
            cells.append(c)
    cells.sort()
    print(f"  Row {r}: cols {cells}")

